//! Canonical signed-payload tests.
//!
//! The byte layout is the cross-language contract between the Rust
//! contract and any client that produces vendor signatures (the
//! TypeScript sandbox suite asserts the same vector).

use super::*;
use ed25519_dalek::Signature;

/// Shared vectors generated by `scripts/gen-vectors.ts` and consumed by
/// `tests/vectors.test.ts`. The Rust side asserts byte-for-byte equality
/// with its own Borsh layout and verifies every Ed25519 signature, so a
/// divergence in either language fails a test in both directions.
const SHARED_VECTORS: &str = include_str!("../../../tests/vectors.json");

/// The reference test vector. The exact same field values are asserted
/// byte-for-byte in `tests/sandbox/borsh_invoice.ts`.
const CANONICAL_VECTOR_HEX: &str = "0c000000696e766f6963656775617264010000000700000073616e64626f781b000000696e766f69636567756172642e756e69742e746573742e6e6561721500000076656e646f722e756e69742e746573742e6e6561720700000000000000150000007061796f75742e756e69742e746573742e6e656172b2c9062ab62fc14c020000000000000080d8db7000000000";

#[test]
fn canonical_bytes_match_the_documented_layout() {
    let inv = invoice(
        vendor_acct(),
        7,
        payout_acct(),
        42_424_242_424_242_424_242,
        1_893_456_000,
    );
    assert_eq!(inv.canonical_bytes(), hex(CANONICAL_VECTOR_HEX));
}

#[test]
fn canonical_bytes_are_deterministic() {
    let a = invoice_valid_at(1, yocto(1), T0_SEC);
    let b = invoice_valid_at(1, yocto(1), T0_SEC);
    assert_eq!(a.canonical_bytes(), b.canonical_bytes());
}

/// Every signed field must influence the bytes: flipping exactly one
/// field must change the message (and therefore invalidate a signature
/// produced over the original).
#[test]
fn every_field_is_bound_by_the_canonical_bytes() {
    let base = invoice(vendor_acct(), 7, payout_acct(), yocto(3), 1_900_000_000);
    let bytes = base.canonical_bytes();

    let mutated = |m: fn(&mut crate::invoice::SignedInvoice)| {
        let mut inv = base.clone();
        m(&mut inv);
        inv.canonical_bytes()
    };

    assert_ne!(
        mutated(|i| i.protocol_id = "otherproto".into()),
        bytes,
        "protocol_id is signed"
    );
    assert_ne!(
        mutated(|i| i.protocol_version += 1),
        bytes,
        "protocol_version is signed"
    );
    assert_ne!(
        mutated(|i| i.network_id = "testnet".into()),
        bytes,
        "network_id is signed"
    );
    assert_ne!(
        mutated(|i| i.contract_id = vendor2_acct()),
        bytes,
        "contract_id is signed"
    );
    assert_ne!(
        mutated(|i| i.vendor_id = vendor2_acct()),
        bytes,
        "vendor_id is signed"
    );
    assert_ne!(
        mutated(|i| i.nonce += 1),
        bytes,
        "nonce is signed"
    );
    assert_ne!(
        mutated(|i| i.recipient = payout2_acct()),
        bytes,
        "recipient is signed"
    );
    assert_ne!(
        mutated(|i| i.amount = crate::types::U128(yocto(4))),
        bytes,
        "amount is signed"
    );
    assert_ne!(
        mutated(|i| i.expiration_unix_sec += 1),
        bytes,
        "expiration is signed"
    );
}

#[test]
fn domain_validation_rejects_foreign_domains() {
    let good = invoice_valid_at(1, yocto(1), T0_SEC);
    assert!(good.validate_domain("sandbox", &contract_acct()).is_ok());

    let mut inv = good.clone();
    inv.protocol_id = "other".into();
    assert_eq!(inv.validate_domain("sandbox", &contract_acct()), Err("E_DOMAIN_PROTOCOL"));

    let mut inv = good.clone();
    inv.protocol_version = 2;
    assert_eq!(inv.validate_domain("sandbox", &contract_acct()), Err("E_DOMAIN_VERSION"));

    let mut inv = good.clone();
    inv.network_id = "testnet".into();
    assert_eq!(inv.validate_domain("sandbox", &contract_acct()), Err("E_DOMAIN_NETWORK"));

    let mut inv = good;
    inv.contract_id = vendor2_acct();
    assert_eq!(inv.validate_domain("sandbox", &contract_acct()), Err("E_DOMAIN_CONTRACT"));
}

/// A signature over a *correct* payload that was produced for a
/// different protocol/network/contract must be rejected by domain
/// validation, independent of Ed25519 correctness.
#[test]
#[should_panic(expected = "E_DOMAIN_NETWORK")]
fn signature_for_another_network_is_rejected() {
    let (mut contract, key) = setup(T0_SEC);
    let mut inv = invoice_valid_at(1, yocto(1), T0_SEC);
    inv.network_id = "testnet".to_string();
    // Validly signed — but for the wrong network.
    let sig = sign(&key, &inv);
    testing_env!(ctx(&agent_acct(), T0_SEC));
    let _ = contract.pay_invoice(inv, sig);
}

/// Cross-language check: the shared vectors produced by the TypeScript
/// tooling must match Rust's canonical Borsh bytes and Ed25519 signatures.
#[test]
fn shared_typescript_vectors_match_rust() {
    let v: near_sdk::serde_json::Value =
        near_sdk::serde_json::from_str(SHARED_VECTORS).expect("valid vectors.json");

    assert_eq!(v["protocol_id"], crate::config::PROTOCOL_ID);
    assert_eq!(
        v["protocol_version"].as_u64().unwrap(),
        crate::config::PROTOCOL_VERSION as u64
    );

    let seed: [u8; 32] = hex(v["signing_seed_hex"].as_str().unwrap())
        .try_into()
        .expect("32-byte seed");
    let signing = SigningKey::from_bytes(&seed);
    let verifying = signing.verifying_key();
    assert_eq!(
        super::pk_of(&signing).to_string(),
        v["public_key"].as_str().unwrap()
    );

    let cases = v["cases"].as_array().expect("cases array");
    assert!(cases.len() >= 4, "need valid + changed-amount/recipient/domain cases");

    let reference_sig = Signature::from_slice(&hex(
        v["reference_signature_hex"].as_str().unwrap(),
    ))
    .expect("valid reference signature");

    let mut valid_hex: Option<String> = None;
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let inv = case["invoice"].as_object().unwrap();
        let invoice = SignedInvoice {
            protocol_id: inv["protocol_id"].as_str().unwrap().to_string(),
            protocol_version: inv["protocol_version"].as_u64().unwrap() as u32,
            network_id: inv["network_id"].as_str().unwrap().to_string(),
            contract_id: inv["contract_id"].as_str().unwrap().parse().unwrap(),
            vendor_id: inv["vendor_id"].as_str().unwrap().parse().unwrap(),
            nonce: inv["nonce"].as_str().unwrap().parse().unwrap(),
            recipient: inv["recipient"].as_str().unwrap().parse().unwrap(),
            amount: crate::types::U128(inv["amount"].as_str().unwrap().parse().unwrap()),
            expiration_unix_sec: inv["expiration_unix_sec"]
                .as_str()
                .unwrap()
                .parse()
                .unwrap(),
        };

        let bytes = invoice.canonical_bytes();
        let expected_hex = case["canonical_hex"].as_str().unwrap();
        assert_eq!(bytes, hex(expected_hex), "canonical bytes for {name}");

        let signature = Signature::from_slice(&hex(case["signature_hex"].as_str().unwrap()))
            .expect("valid signature");
        assert!(
            verifying.verify_strict(&bytes, &signature).is_ok(),
            "signature for {name} must verify"
        );

        // Domain validation must agree with the recorded Rust error code.
        let expected_domain_error = case["domain_error"].as_str();
        let actual = invoice
            .validate_domain(
                v["network_id"].as_str().unwrap(),
                &v["contract_id"].as_str().unwrap().parse().unwrap(),
            )
            .err();
        assert_eq!(actual, expected_domain_error, "domain result for {name}");

        if name == "valid" {
            valid_hex = Some(expected_hex.to_string());
            assert!(
                verifying.verify_strict(&bytes, &reference_sig).is_ok(),
                "reference signature must verify for the valid case"
            );
        } else {
            assert_ne!(
                Some(expected_hex.to_string()),
                valid_hex,
                "{name} must change the canonical bytes"
            );
            assert!(
                verifying.verify_strict(&bytes, &reference_sig).is_err(),
                "reference signature must not verify for {name}"
            );
        }
    }
    assert!(valid_hex.is_some(), "a valid vector is required");
}
